     }

     * {
       box-sizing: border-box;
     }

     html {
       font-family: Inter, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
       background: var(--bg);
       color: var(--text);
     }

     body {
       margin: 0;
       min-height: 100vh;
       background:
         radial-gradient(circle at top, #ffffff 0, #f3f6fb 52%, #e8eefb 100%);
     }

     .skip-link {
       position: absolute;
       top: 1rem;
       left: 1rem;
       transform: translateY(-200%);
       padding: 0.75rem 1rem;
       border-radius: 999px;
       background: var(--text);
       color: #ffffff;
       font-weight: 700;
       text-decoration: none;
       z-index: 20;
     }

     .skip-link:focus {
       transform: translateY(0);
     }

     :focus-visible {
       outline: 3px solid var(--focus);
