       box-shadow: var(--shadow);
     }

     .media-panel,
     .detail-panel {
       min-width: 0;
     }

     .media-frame {
       margin: 0;
       padding: 0.75rem;
       border-radius: 1.25rem;
       background: linear-gradient(180deg, #f8faff 0%, #eef3ff 100%);
       border: 1px solid var(--border);
     }

     .media-frame img {
       display: block;
       width: 100%;
       aspect-ratio: 4 / 3;
       object-fit: cover;
       border-radius: 1rem;
       max-width: 100%;
     }

     .eyebrow {
       display: inline-flex;
       align-items: center;
       gap: 0.5rem;
       margin: 0 0 1rem;
       padding: 0.45rem 0.8rem;
       border-radius: 999px;
       background: var(--surface-muted);
       color: var(--accent-strong);
       font-size: 0.875rem;
       font-weight: 700;
     }

     h1 {
