       line-height: 1.05;
       letter-spacing: -0.03em;
     }

     .lead,
     .meta-list dd,
     .meta-list dt,
     .dialog-copy,
     .status {
       overflow-wrap: anywhere;
     }

     .lead {
       margin: 0 0 1.5rem;
       color: var(--text-muted);
       font-size: 1rem;
       line-height: 1.6;
     }

     .meta-list {
       margin: 0 0 1.5rem;
       padding: 0;
       display: grid;
       grid-template-columns: repeat(2, minmax(0, 1fr));
       gap: 1rem;
     }

     .meta-list div {
       padding: 1rem;
       border: 1px solid var(--border);
       border-radius: 1rem;
       background: #fbfcff;
