       gap: 0.75rem;
       align-items: center;
     }

     button {
       border: 0;
       border-radius: 999px;
       padding: 0.95rem 1.2rem;
       font: inherit;
       font-weight: 700;
       cursor: pointer;
       transition: background-color 160ms ease, transform 160ms ease;
     }

     button:hover {
       transform: translateY(-1px);
     }

     .primary-action {
       background: var(--accent);
       color: #ffffff;
     }

