     .secondary-action:hover,
     .secondary-action:focus-visible {
       background: #e2eaff;
     }

     .status {
       margin: 1rem 0 0;
       min-height: 1.5rem;
       color: var(--text-muted);
       font-weight: 600;
     }

     dialog {
       width: min(100% - 2rem, 30rem);
       padding: 0;
       border: 0;
       border-radius: 1.5rem;
       box-shadow: 0 30px 90px rgba(15, 23, 42, 0.28);
       background: var(--surface);
       color: var(--text);
     }

     dialog::backdrop {
       background: rgba(23, 32, 51, 0.62);
       backdrop-filter: blur(6px);
     }

     .dialog-shell {
       padding: 1.5rem;
     }

     .dialog-title {
       margin: 0 0 0.75rem;
       font-size: 1.5rem;
       line-height: 1.2;
     }

     .dialog-copy {
       margin: 0 0 1.5rem;
       color: var(--text-muted);
       line-height: 1.6;
     }
